import unittest

from median import median


class TestMedian(unittest.TestCase):
    def test_odd_length_list(self):
        self.assertEqual(median([3, 1, 2]), 2)
        self.assertEqual(median([7, 1, 5, 3, 9]), 5)

    def test_even_length_list(self):
        self.assertEqual(median([4, 1, 3, 2]), 2.5)
        self.assertEqual(median([10, 20]), 15)

    def test_empty_list(self):
        self.assertIsNone(median([]))

    def test_duplicate_values(self):
        self.assertEqual(median([2, 2, 2, 2]), 2)
        self.assertEqual(median([5, 1, 5, 3, 5]), 5)

    def test_negative_numbers(self):
        self.assertEqual(median([-3, -1, -2]), -2)
        self.assertEqual(median([-10, 5, -4, 2]), -1.0)

    def test_single_element(self):
        self.assertEqual(median([42]), 42)

    def test_does_not_mutate_input(self):
        numbers = [3, 1, 2]
        median(numbers)
        self.assertEqual(numbers, [3, 1, 2])


if __name__ == "__main__":
    unittest.main()
